function dropRepeats(head: ListNode | null): ListNode | null {
  const dummy = new ListNode(0);
  let tail = dummy;
  for (let p = head; p; p = p.next) {
    if (tail === dummy || tail.val !== p.val) {
      tail.next = p;
      tail = p;
    }
  }
  tail.next = null;
  return dummy.next;
}

