class Solution:
    def dropRepeats(self, head: Optional[ListNode]) -> Optional[ListNode]:
        dummy = ListNode(0)
        tail = dummy
        p = head
        while p:
            if tail is dummy or tail.val != p.val:
                tail.next = p
                tail = p
            p = p.next
        tail.next = None
        return dummy.next

